/* All UI text is real DOM; art assets are independently layered. */
'use strict';
const E=Hotpot, C=JianghuCustomers, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], KEY='yiguojianghu-save-v1';
let state;try{state=E.restore(localStorage.getItem(KEY))||E.fresh();}catch{state=E.fresh();}
let selected=0,paused=state.phase==='service',speed=1,modalType='',draft=null,planTable=0,activeRound=0,planStep=0,toastTimer,saveTimer=0,opera=null,last=performance.now();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥ '+Math.round(n).toLocaleString('zh-CN');
const catSprite=(n,cls='')=>`<div class="sprite cat-${n} ${cls}" aria-hidden="true"></div>`;
const person=(n,cls='')=>`<div class="sprite customer ${cls}" style="--portrait-x:${(n%4)*100/3}%;--portrait-y:${Math.floor(n/4)*100/3}%" aria-hidden="true"></div>`;
const iconFood=id=>`<span class="food-icon">${E.F[id].icon}</span>`;
function save(){try{localStorage.setItem(KEY,E.serialize(state));$('#save-status').textContent='已保存 · 本浏览器可继续';}catch{$('#save-status').textContent='浏览器未允许存档，请勿关闭';}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3100);}
const sound=JianghuAudio.create(state.muted);
state.muted=sound.settings.muted;
function chime(kind='tap'){sound.play(kind);}
function syncSound(){sound.update({phase:state.phase,paused,panel:$('#modal').open,opera:!!opera?.running||state.stats?.showRemaining>0,hidden:document.hidden||modalType==='cinema',eating:state.tables.filter(t=>t.status==='eating').length,rain:state.day===3});}
function soundStatus(){const info=sound.info(),button=$('#sound');button.textContent=sound.settings.muted?'♪̸':'♪';button.setAttribute('aria-label','江湖留声机：音乐与音效设置');button.title=sound.settings.muted?'声音已关 · 点击调整':'江湖留声机 · '+info.title;button.classList.toggle('music-playing',info.playing);const text=$('#audio-status');if(text)text.textContent=info.error||(!info.active?'点一下「开启声音」，请乐师开场。':sound.settings.muted?'已静音，老街歇歇声。':info.loading?'乐师正在调弦…':info.opera?'锣鼓上场 · 配乐已轻轻退后':info.title+' · '+info.detail);const mute=$('[data-action="audio-mute"]');if(mute){mute.textContent=sound.settings.muted?'开启声音':'全部静音';mute.setAttribute('aria-pressed',String(sound.settings.muted));}}
sound.onChange(soundStatus);
function soundModal(){const p=sound.settings;modal('江湖留声机','一曲烟火，一耳江湖',`<div class="audio-hero"><span class="audio-seal">声</span><div><h3>老街起锅</h3><p id="audio-status" role="status"></p></div></div><p class="modal-intro">贝斯、吉他带着利落鼓点，竹笛、拨弦和小锣在锅边接招。曲子会随营业阶段换，变脸时让锣鼓站前排。</p><div class="audio-sliders">${[['music','江湖配乐','三段原创器乐 · 自动循环'],['effects','手边动静','开锅、碗碟、铜钱、猫猫和亮相'],['ambience','烟火环境','锅底咕嘟 · 雨天细声']].map(([id,title,sub])=>`<label class="audio-row"><span><b>${title}</b><small>${sub}</small></span><input type="range" min="0" max="100" step="1" value="${Math.round(p[id]*100)}" data-volume="${id}" aria-label="${title}音量"><output id="volume-${id}">${Math.round(p[id]*100)}%</output></label>`).join('')}</div><div class="audio-audition"><span>听听小动静</span><button data-action="audio-preview" data-id="cat">摸猫 ♡</button><button data-action="audio-preview" data-id="coin">收钱</button><button data-action="audio-preview" data-id="opera-hit">变脸亮相</button></div><p class="mini-note">第一次点按后开始播放；离开页面自动安静。营业加速不会让音乐变快。声音设置会记住。</p>`,'audio',`<div class="modal-footer"><div class="buttons"><button data-action="audio-retry">重试配乐</button><button data-action="audio-mute" aria-pressed="${p.muted}">${p.muted?'开启声音':'全部静音'}</button></div><button class="primary" data-action="modal-close">好，继续开锅 →</button></div>`);soundStatus();}

function pop(id,text){let t=$(`[data-table="${id}"]`);if(!t)return;let f=document.createElement('span');f.className='float-pop';f.style.left=t.style.left;f.style.top=t.style.top;f.textContent=text;$('#float-layer').append(f);setTimeout(()=>f.remove(),1600);}
function modal(title,eyebrow,body,type,footer=''){stopCinema();modalType=type;$('#modal').dataset.kind=type;$('#modal-content').innerHTML=`<div class="modal-header"><div><span class="eyebrow">${esc(eyebrow)}</span><h2>${esc(title)}</h2></div><button class="close-modal" data-action="modal-close" aria-label="关闭面板">×</button></div>${body}${footer}`;if(!$('#modal').open)$('#modal').showModal();syncSound();}
function closeModal(){stopCinema();if(opera?.running){opera.running=false;}$('#modal').close();modalType='';opera=null;save();render();}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
function eventProgress(){if(!state.stats)return '今日目标';let a=state.stats,g=a.records.filter(r=>r.score>=80).length;return `${a.served} 桌已招待 · ${g} 桌好评`;}
function render(){
 $('#day-label').textContent=`第 ${state.day} 天 · ${state.day===3?'小雨':'晴'}`;
 let mins=17*60+Math.floor(state.elapsed*1.3);$('#time-label').textContent=state.phase==='prep'?'开门前 / 备一锅好味':state.phase==='settlement'?'打烊后 / 翻翻今天的故事':`${String(Math.floor(mins/60)).padStart(2,'0')}:${String(mins%60).padStart(2,'0')} · ${paused?'稍歇一会儿':'人间正沸腾'}`;
 $('#cash').textContent=money(state.cash);$('#rep').textContent=state.rep;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').classList.toggle('active',paused);$('#pause').setAttribute('aria-label',paused?'继续营业':'暂停营业');$('#speed').textContent=speed+'×';soundStatus();syncSound();$('#rain').classList.toggle('active',state.day===3&&state.phase==='service');
 $('#phase-label').textContent=state.phase==='prep'?'备菜中':state.phase==='settlement'?'今日打烊':paused?'营业暂停':'营业中';$('#progress-label').textContent=state.stats?` · ${state.stats.served}/${state.schedule.length} 桌`:'';
 $('#show-hint').textContent=state.day<2?'第 2 天解锁':state.stats?.showRemaining>0?'正在演出':state.stats?.showDone?'今晚已演出':state.showPlan.at!==null?'已预约 '+state.showPlan.at+' 秒':'短场 / 压轴 · 排场次';
 $('.restaurant').classList.toggle('cat-corner',!!state.upgrades.cat);$('.restaurant').classList.toggle('festival',state.badges.includes('一锅江湖'));
 const ev=E.event(state);$('#objective').innerHTML=`<small>今日小目标 · DAY ${state.day}</small><h3>${ev.name}</h3><p>${ev.goal}</p><div class="target-progress"><span>${eventProgress()}</span></div><button class="event-link" data-action="event-detail">完成领 ${money(ev.reward)} 与纪念章 ↗</button>`;
 $('#close-day').disabled=state.phase!=='service';$('#close-day').textContent=state.closing?'收尾中…':'提前打烊';
 $('#scene-hint').textContent=state.phase==='prep'?'先看看预约、补好食材，再开门迎客。':state.phase==='settlement'?'今天的烟火留在账本里，明天还要开门。':state.upgrades.staff?'伙计会按分工接桌，你可以专心照顾重点饭局。':'点击桌子配锅点单；点猫咪陪客人玩。空格键可暂停。';
 let stamp=$('.paused-stamp');if(paused&&state.phase==='service'){if(!stamp){stamp=document.createElement('div');stamp.className='paused-stamp';stamp.textContent='歇一歇 · 已暂停';$('.restaurant').append(stamp);}}else stamp?.remove();
 renderTables();renderSide();renderMobile();renderOpera();renderCity();let residents=$('#resident-cats');if(!residents){residents=document.createElement('div');residents.id='resident-cats';$('.restaurant').append(residents);}residents.innerHTML=state.phase!=='service'?state.cats.map((c,i)=>`<button class="resident-cat" style="left:${18+i*26}%" data-action="cats" aria-label="看看猫掌柜${c.name}">${catSprite(i)}<span>${c.name}在等你 ♡</span></button>`).join(''):'';
}
function renderOpera(){let el=$('#live-opera');const running=state.phase==='service'&&state.stats?.showRemaining>0;if(!running){el?.remove();return;}if(!el){el=document.createElement('button');el.id='live-opera';el.className='live-opera';el.dataset.action='cinema';el.innerHTML='<img src="assets/performer.png" alt=""><span></span>';$('.restaurant').append(el);}el.querySelector('span').textContent='▶ 看变脸 · '+Math.ceil(state.stats.showRemaining)+' 秒';}

function renderTables(){let tables=state.tables.length?state.tables:Array.from({length:state.upgrades.tables?6:4},(_,id)=>({id,status:'empty'}));let six=tables.length===6;$('.restaurant').classList.toggle('six-tables',six);let pos=six?[[25,55],[51,55],[76,55],[25,77],[51,77],[76,77]]:[[31,55],[64,55],[31,77],[64,77]];let layer=$('#table-layer');for(let t of tables){let node=$(`[data-table="${t.id}"]`);if(!node){node=document.createElement('div');node.dataset.table=t.id;layer.append(node);}node.style.setProperty('--mobile-x',(t.id%2===0?27:71)+'%');node.style.setProperty('--mobile-y',(six?[34,57,80]:[45,77])[Math.floor(t.id/2)]+'%');node.className=`table-group ${t.status} ${selected===t.id&&state.phase==='service'?'selected':''}`;node.style.left=pos[t.id][0]+'%';node.style.top=pos[t.id][1]+'%';if(six)node.style.width='21%';else node.style.width='';
 let occupied=['waiting','eating'].includes(t.status);let soup=t.plan?`linear-gradient(90deg,${t.plan.broths.map((b,i,a)=>`${E.B[b].color} ${i/a.length*100}% ${((i+1)/a.length)*100}%`).join(',')})`:'#b4b198';let food=t.status==='eating'&&t.round>=0?t.m.rounds[t.round][0]:null;
 let signature=[t.status,t.guest?.id,t.guest?.size,t.cast?.join(','),t.round,t.cat,t.petCount,t.catActive,t.seat,food,t.message,t.plan?.pot,selected===t.id].join('|');if(node.dataset.sig!==signature){node.dataset.sig=signature;node.innerHTML=`${occupied?Array.from({length:t.guest.size},(_,i)=>person(C.forTable(t)[i],`guest g${i+1}`)).join(''):''}<div class="table-surface"></div><div class="dish d1"></div><div class="dish d2"></div>${t.status!=='empty'?`<div class="pot"><div class="pot-soup" style="--soup:${soup}"></div>${t.status==='eating'?'<div class="steam">∿∿</div>':''}</div>`:''}${food?`<span class="tiny-food">${E.F[food].icon}</span>`:''}<button class="table-main" data-action="select" data-id="${t.id}" aria-label="${t.id+1}号桌，${occupied?esc(t.guest.name):t.status==='dirty'?'等待收台':'空桌'}"></button><div class="table-label">${t.id+1} ${E.seatName(t.seat||E.seatType(state,t.id,tables.length))} <em>${t.status==='empty'?'等你开锅':t.status==='waiting'?'配锅点单':t.status==='dirty'?'收台 +':'第 '+Math.max(1,t.round+1)+' 轮'}</em></div>${occupied&&t.catActive?`<button class="table-cat" data-action="pet" data-id="${t.id}" aria-label="让${state.cats[t.cat].name}陪${t.id+1}桌客人撸猫">${catSprite(t.cat)}<span class="pet-tip">摸摸 ${state.cats[t.cat].name} ♡</span></button>`:''}${occupied&&(t.id===selected||t.status==='waiting')?`<div class="table-bubble">${esc(t.status==='waiting'?'“'+t.guest.quote+'”':t.message)}</div>`:''}${t.status==='eating'?'<div class="mini-progress"><span></span></div>':''}`;}
 let bar=node.querySelector('.mini-progress span');if(bar)bar.style.width=Math.min(100,t.progress/t.m.duration*100)+'%';}
 [...layer.children].filter(n=>Number(n.dataset.table)>=tables.length).forEach(n=>n.remove());
}
function moreModal(){
 modal('小店里的事','账本、戏台与老街消息',`<div class="more-grid">${[['city','街坊江湖','拼桌、研发、人情与挑战'],['owner','梅嬢嬢当班','聊两句，给客人添茶'],['ledger','翻翻账本','今天赚了多少'],['events','老街头条','看看今日目标'],['show','川剧变脸','邀请师傅登台'],['sound','音乐与音效','江湖留声机'],['help','怎么玩','再看一眼诀窍'],['close','提前打烊','招待完当前客人']].map(([id,title,sub])=>`<button data-action="${id}" ${id==='close'&&state.phase!=='service'?'disabled':''}><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div>`,'more');
}
function renderMobile(){
 const el=$('#mobile-service');if(!el)return;const ev=E.event(state);let html='';
 if(state.phase==='prep'){
  html=`<div class="mobile-prep-heading"><strong>今天怎么开店？</strong><button class="text-button" data-action="event-detail">看目标 ↗</button></div><div class="mobile-modes">${ev.modes.map(([id,name,desc])=>`<button class="${state.mode===id?'active':''}" data-action="mode" data-id="${id}" aria-pressed="${state.mode===id}"><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="mobile-actions"><button data-action="stock">检查菜篮子</button><button class="primary" data-action="open">开门迎客 →</button></div>`;
 }else if(state.phase==='settlement'){
  html=`<div class="mobile-prep-heading"><strong>今天招待了 ${state.stats.served} 桌</strong><span>净收益 ${money(state.stats.profit)}</span></div><p class="mobile-note">${state.stats.goal?'今日小目标完成，明天还有新饭局。':'翻翻账本，下一锅可以更好。'}</p><div class="mobile-actions"><button data-action="settlement">翻翻今天的账</button><button class="primary" data-action="next">明天开门 →</button></div>`;
 }else{
  let t=state.tables[selected];
  html=`<nav class="mobile-table-tabs" aria-label="选择桌子">${state.tables.map(t=>`<button class="${t.id===selected?'active':''} ${t.status}" data-action="select" data-id="${t.id}" aria-pressed="${t.id===selected}" aria-label="选择${t.id+1}号桌，${{waiting:'待点单',eating:'用餐中',dirty:'待收台',empty:'空桌'}[t.status]}">${t.id+1}<small>${{waiting:'点单',eating:'开涮',dirty:'收台',empty:'空桌'}[t.status]}</small></button>`).join('')}</nav>`;
  if(t&&['waiting','eating'].includes(t.status)){
   const cat=state.cats[t.cat],cool=t.petCount>=1;
   html+=`<div class="mobile-guest-heading">${person(C.forTable(t)[0])}<div><strong>${t.guest.name}</strong><small>${t.status==='waiting'?'等候余 '+Math.max(0,Math.ceil(t.patience-t.wait))+' 秒 · 预算 '+money(t.guest.budget):'第 '+Math.max(1,t.round+1)+' 轮 · 餐食 '+Math.round(t.score)+' / 心情 '+(t.mood||0)}</small></div><button class="seat-link" data-action="seats">${E.seatName(t.seat)} ↗</button></div><div class="mobile-need-line">${t.status==='waiting'?t.guest.tastes.map(v=>v==='spicy'?'要辣':'要清淡').join(' / ')+' · '+(t.guest.meat?'肉要管够 · ':'')+(t.guest.style==='rush'?'全程限时 ':'用餐期望 ')+t.guest.limit+' 秒':esc(t.message)}</div><div class="mobile-actions">${t.status==='waiting'?`<button class="primary" data-action="plan" data-id="${t.id}">${t.special?'重点饭局 · 拿主意':'配锅点单'} →</button>`:t.addOffer?`<button class="primary" data-action="add" data-id="${t.id}">加盘肥牛 · ¥28</button>`:`<button data-action="recipes">看看招牌菜单</button>`}${t.pairOffer&&t.status==='waiting'?'<button data-action="pair">川剧同好 · 拼桌？</button>':`<button data-action="pet" data-id="${t.id}" ${cool?'disabled':''}>${t.petCount?'已安排'+cat.name:'选猫来陪吃 ♡'}</button>`}</div>`;
  }else{
   const next=state.tables.find(x=>x.status==='waiting');
   html+=`<div class="mobile-empty"><strong>${t?.status==='dirty'?'这桌吃得巴适，收拾一下吧':'留一盏灯，等下一桌客人'}</strong><small>${t?.status==='dirty'?t.message:'猫咪和锅都在等你。'}</small></div><div class="mobile-actions">${t?.status==='dirty'?`<button class="primary" data-action="clean" data-id="${t.id}">亲自收台</button>`:`<button data-action="stock">看看菜篮子</button>`}${next?`<button class="primary" data-action="select" data-id="${next.id}">去 ${next.id+1} 桌点单 →</button>`:'<button data-action="cats">看看猫掌柜</button>'}</div>`;
  }
 }
 if(el.innerHTML!==html)el.innerHTML=html;
}

function tags(g){return `<div class="tags">${g.tastes.map(t=>`<span class="tag ${t}">${t==='spicy'?'想吃辣':'要清淡'}</span>`).join('')}${g.meat?'<span class="tag meat">肉要管够</span>':''}<span class="tag">${g.size} 人${g.style==='rush'?' · 赶时间':g.style==='quiet'?' · 爱安静':''}</span></div>`;}
function renderSide(){let html='';const ev=E.event(state);if(state.phase==='prep'){
 $('#panel-heading').textContent='今日开锅记';html=`<span class="event-label">${ev.kicker}</span><h3>${ev.name}</h3><p>${ev.story}</p><div class="mode-options">${ev.modes.map(m=>`<button class="mode-option ${state.mode===m[0]?'active':''}" data-action="mode" data-id="${m[0]}"><strong>${m[1]}</strong><small>${m[2]}</small></button>`).join('')}</div><button class="primary wide side-start" data-action="open">开门迎客 <span>→</span></button><div class="note-line"><span>完成事件奖励</span><b>${money(ev.reward)} ＋ 纪念章</b></div><div class="small-heading">今晚预约 · 先认认脸</div>${E.G.filter((g,i)=>[0,1,2].includes(i)).slice(0,2).map((g,i)=>{let lookup=E.decorateGuest(state,E.clone(E.G[E.dayGuests(state)[i]]));return `<div class="arrival-row"><span class="arrival-num">0${i+1}</span><div><strong>${lookup.name}</strong><small>${lookup.quote}</small></div></div>`;}).join('')}<p class="mini-note">${state.day===1?'第一批食材已备好。先照顾老罗那桌，试试鸳鸯锅。':'先到「买菜备货」检查库存，再看看设施能否升级。'}<br>第 ${state.day} 天 · ${state.day>=3?'已解锁小份菜':'随时暂停，慢慢想'}</p>`;
 }else if(state.phase==='settlement'){$('#panel-heading').textContent='今日收工啦';let a=state.stats;html=`<span class="event-label">蒸汽散去，故事留下</span><h3>又养熟了几位街坊。</h3><p>今晚招待 ${a.served} 桌，留下 ${a.records.filter(r=>r.score>=80).length} 桌好评。猫咪被摸了 ${a.pets} 回，呼噜声都更响啦。</p><div class="note-line"><span>营业净收益</span><b>${money(a.profit)}</b></div><div class="note-line"><span>事件额外奖金</span><b>${money(a.reward)}</b></div><p>${a.goal?'小目标达成，今天的纪念章收好啦。':'有一点遗憾也没关系，账本里藏着明天的办法。'}</p><button class="primary wide" data-action="settlement">展开打烊账本 →</button><div class="small-heading">刚刚发生的小事</div>${state.logs.slice(0,4).map(l=>`<div class="log-entry">${esc(l)}</div>`).join('')}`;
 }else{$('#panel-heading').textContent='今晚的饭局';let t=state.tables[selected];if(t&&['waiting','eating'].includes(t.status)){let g=t.guest,c=state.cats[t.cat];html+=`<article class="selected-guest"><span class="table-num">${String(t.id+1).padStart(2,'0')}</span><span class="event-label">${t.status==='waiting'?'等一口好锅':'咕嘟咕嘟 · 开吃啦'}</span><h3>${g.name}</h3>${tags(g)}<div class="guest-quote">“${esc(t.message)}”</div><div class="guest-facts"><div>整桌预算<strong>${money(g.budget)}</strong></div><div>${t.status==='waiting'?'等待耐心':'当前评价'}<strong>${t.status==='waiting'?Math.max(0,Math.ceil(t.patience-t.wait))+' 秒':Math.round(t.score)+' 分'}</strong></div></div>`;
 if(t.status==='waiting'){html+=`<div class="wait-meter"><span style="width:${Math.max(0,1-t.wait/t.patience)*100}%"></span></div><button class="primary wide side-start" data-action="plan" data-id="${t.id}">配锅点单 →</button>`;}else{html+=`<div class="stat-bars">${[['鲜味',t.fresh,''],['浓度',t.rich,'rich']].map(([n,v,cl])=>`<div class="stat-bar">${n}<div class="dots ${cl}">${[1,2,3].map(i=>`<i class="${i<=v?'on':''}"></i>`).join('')}</div></div>`).join('')}</div>${t.m.rounds.map((r,i)=>`<div class="round-strip ${i===t.round?'active':i<t.round?'done':''}">${i<t.round?'✓':i===t.round?'●':'○'} 第 ${i+1} 轮 · ${r.map(id=>E.F[id].short).join(' ＋ ')}</div>`).join('')}${t.addOffer?'<button class="secondary wide" style="margin-top:10px" data-action="add" data-id="'+t.id+'">客人想加盘肥牛 · ¥28</button>':''}`;}
 html+=`<div class="cat-action">${catSprite(t.cat)}<div><b>${t.petCount?c.name+'已安排陪伴':'选一位猫掌柜'}</b><small>餐食 ${Math.round(t.score||0)} · 心情 ${t.mood||0}</small><button data-action="pet" data-id="${t.id}">安排陪伴</button><button data-action="seats">${E.seatName(t.seat)} · 换座</button></div></div></article>`;
 }else{html+=`<p>${t?.status==='dirty'?'客人吃得满意，顺手把这桌收拾一下吧。':'有空就摸摸猫、看看库存。客人会陆续来。'}</p>${t?.status==='dirty'?'<button class="secondary wide" data-action="clean" data-id="'+t.id+'">梅嬢嬢亲自收台</button>':''}`;}
 html+=state.tables.map(t=>`<button class="table-card ${t.id===selected?'selected':''}" data-action="select" data-id="${t.id}"><span class="number">${String(t.id+1).padStart(2,'0')}</span><span><strong>${t.status==='empty'?'空桌 · 留一盏灯':t.guest.name}</strong><small>${t.status==='eating'?E.P[t.plan.pot].name+' · '+Math.round(t.score)+' 分':t.status==='waiting'?'“'+esc(t.guest.quote.slice(0,12))+'…”':t.status==='dirty'?'好好收拾，等下一桌':'晚风和猫先坐一会儿'}</small></span><span class="state">${{empty:'待客',waiting:'待配锅',eating:'用餐中',dirty:'待收台'}[t.status]}</span></button>`).join('');html+=`<div class="small-heading">老街小动静</div>${state.logs.slice(0,2).map(l=>`<div class="log-entry">${esc(l)}</div>`).join('')}`;
 }
 if($('#side-panel').innerHTML!==html)$('#side-panel').innerHTML=html;
}
function openPlan(id){const t=state.tables[id];if(t?.status!=='waiting')return;selected=id;planTable=id;draft=E.defaultPlan(state,t.guest);if(t.special)draft.rounds=[[],[],[]];activeRound=0;planStep=0;renderPlan();render();}
function renderPlan(){
 const t=state.tables[planTable];if(!t)return closeModal();const g=t.guest,m=E.metrics(state,g,draft),choices=E.planChoices(state,t),undecided=t.special&&!draft.choice;
 let choice=t.special?`<section class="special-choice"><span class="event-label">今日重点饭局 · 嬢嬢拿主意</span>${undecided?`<h3>这桌，你想怎么招待？</h3><div class="choice-grid">${choices.map(c=>{const v=E.metrics(state,g,c.plan);return `<button data-action="plan-choice" data-id="${c.id}"><strong>${c.name}</strong><p>${c.desc}</p><small>消费 ¥${v.price} · 成本 ¥${v.cost}<br>等餐＋用餐 ${Math.ceil(v.totalTime)} 秒 · 预计毛利 ¥${Math.round((v.price-v.cost)*10)/10}</small><em>${v.errors.length?v.errors.join(' / '):v.essentialOk?'基本需求都能照顾到':'有基本需求未满足，请调整'}</em></button>`;}).join('')}</div><button class="text-button" data-action="plan-choice" data-id="custom">我想自己配一锅 →</button>`:`<div class="chosen-plan"><strong>${choices.find(c=>c.id===draft.choice)?.name||'嬢嬢亲自搭配'}</strong><button data-action="rechoose">换个招待方案</button></div>`}</section>`:'';
 let body=`<div class="planning-top">${person(C.forTable(t)[0])}<div class="quote">“${esc(g.quote)}”<div style="margin-top:8px">${tags(g)}</div></div><div class="planning-budget">整桌预算<strong>${money(g.budget)}</strong>${g.style==='rush'?'全程限时':'用餐期望'} ${g.limit} 秒</div></div>${choice}`;
 if(!undecided)body+=`<nav class="plan-steps mobile-only" aria-label="配餐步骤">${['选锅','上菜','确认'].map((name,i)=>`<button data-action="plan-step" data-id="${i}" aria-current="${i===planStep?'step':'false'}">${i+1} · ${name}</button>`).join('')}</nav><div class="planning-grid" data-step="${planStep}"><section class="plan-pots"><h3 class="section-title">① 选一口锅</h3>${Object.entries(E.P).map(([id,p])=>`<button class="pot-option ${draft.pot===id?'active':''}" data-action="pot" data-id="${id}" ${p.day>state.day?'disabled':''}><strong>${p.name} · ¥${p.price}</strong><small>${p.day>state.day?'第 '+p.day+' 天解锁':p.desc}</small></button>`).join('')}<div class="broths-container">${draft.broths.map((id,i)=>`<select class="broth-select" aria-label="第 ${i+1} 格锅底" data-broth="${i}">${Object.entries(E.B).filter(([k,b])=>b.day<=state.day).map(([k,b])=>`<option value="${k}" ${id===k?'selected':''}>${b.name}${k==='mushroom'?'（成本 +3）':k==='tomato'?'（成本 +2）':''}</option>`).join('')}</select>`).join('')}</div><label class="plan-small"><input type="checkbox" id="small-portion" ${draft.small?'checked':''} ${state.day<3?'disabled':''}>小份菜 · ${state.day<3?'第 3 天解锁':'售价 / 用料 65%'}</label><label class="plan-small"><input type="checkbox" data-plan-toggle="fast" ${draft.fast?'checked':''}>精切快熟 · 支出 +12，每轮少 4 秒</label>${g.id==='luo'?`<label class="plan-small"><input type="checkbox" data-plan-toggle="discreet" ${draft.discreet?'checked':''}>悄悄留清汤，给老罗面子</label>`:''}${state.unlocks.luoSauce?`<label class="plan-small"><input type="checkbox" data-plan-toggle="sauce" ${draft.sauce==='luo'?'checked':''}>老罗江湖蘸碟 · 红汤搭配 +4 分</label>`:''}${state.city.dishes.length?`<label class="signature-select">用一道研发招牌<select id="plan-signature"><option value="">普通做法</option>${state.city.dishes.map(d=>`<option value="${d.id}" ${draft.signature===d.id?'selected':''}>${esc(d.name)} · 加入${E.F[d.base].short}</option>`).join('')}</select></label>`:''}<div class="recipe-controls"><button data-action="recommend">配一份基础菜单</button><button data-action="clear-plan">清空菜品</button></div><p class="mini-note">菌菇先养鲜，下一轮的肉菜与豆腐才吃得到加成。</p></section><section class="ingredient-section"><h3 class="section-title">② 点菜入轮 <span>每轮最多 2 盘</span></h3><div class="round-picker">${[0,1,2].map(i=>`<button class="${i===activeRound?'active':''}" data-action="round" data-id="${i}">第 ${i+1} 轮</button>`).join('')}</div><div class="ingredients-grid">${E.unlocked(state).map(id=>{let f=E.F[id];return `<button class="food-card" data-action="food" data-id="${id}" ${state.stock[id]<(draft.small?.65:1)?'disabled':''}>${iconFood(id)}<div><strong>${f.name}</strong><small>${f.desc}</small><small><b>¥${Math.round(f.price*(draft.small?.65:1))}</b> · 库存 ${state.stock[id].toFixed(1).replace('.0','')}</small></div><span class="food-add">＋</span></button>`;}).join('')}</div></section><section class="planning-rounds"><h3 class="section-title">③ 看看上菜顺序</h3>${[0,1,2].map(i=>`<div class="serving-round ${i===activeRound?'selected':''}"><header><span>第 ${i+1} 轮 · ${['先开胃','再尽兴','留余香'][i]}</span><button data-action="round" data-id="${i}">选这一轮</button></header>${(draft.rounds[i]||[]).map((id,j)=>`<span class="food-chip">${E.F[id].short}<button data-action="remove-food" data-id="${i},${j}" aria-label="移除${E.F[id].name}">×</button></span>`).join('')||'<span class="round-empty">选择食材加入这一轮</span>'}</div>`).join('')}<div class="eval-box"><div class="eval-row"><span>整桌消费 / 预算</span><b>${money(m.price||0)} / ${money(g.budget)}</b></div><div class="eval-row"><span>菜、锅与服务成本</span><b>¥ ${m.cost||0}</b></div><div class="eval-row"><span>已等 ${Math.ceil(t.wait)} 秒 ＋ 用餐</span><b>${Math.ceil(m.totalTime||0)} / ${g.limit} 秒</b></div><div class="eval-row"><span>预计餐食评价</span><b>${m.score||0} 分</b></div><div class="needs-check">${(m.requirements||[]).map(x=>`<p class="${x.ok?'met':'unmet'}">${x.ok?'✓':'!'} ${x.label}</p>`).join('')}</div>${!m.essentialOk?'<p class="eval-warning">基本需求没照顾好，最高 69 分。撸猫和好戏只能增加心情，不能替代这顿饭。</p>':''}<div class="eval-reasons">${(m.reasons||[]).map(esc).join('<br>')}</div>${m.errors.length?`<div class="eval-warning">${m.errors.join('<br>')}</div>`:''}</div></section></div>`;
 modal(`给 ${planTable+1} 桌配一口好锅`,'点菜单 · 全店暂停，慢慢想',body,'plan',undecided?'':`<div class="modal-footer plan-footer" data-step="${planStep}"><div class="save-recipe-group"><input class="save-name" id="recipe-name" aria-label="套餐名称" maxlength="18" placeholder="给套餐起个名"><button data-action="save-recipe">存为招牌</button></div><div class="buttons"><button data-action="modal-close">再看看</button><button class="mobile-only" data-action="plan-back" ${planStep===0?'disabled':''}>上一步</button><button class="primary mobile-only plan-next" data-action="plan-next">${planStep===0?'下一步：上菜':'下一步：确认'} →</button><button class="primary serve-button" data-action="serve" ${m.errors.length?'disabled':''}>${m.essentialOk?'确认开锅':'按此安排开锅'} · ${money(m.price||0)} →</button></div></div>`);
}
function stockModal(){if(state.challenge)return toast('挑战使用固定库存，不能额外采购。');let body=`<p class="modal-intro">现金 ${money(state.cash)}。每份是供一桌分享的一盘菜。小份按 0.65 份消耗；打烊时超过 8 份的库存会少量报损。采购直接扣现金，已用食材计入当日经营成本。</p><div class="shop-grid">${Object.entries(E.F).map(([id,f])=>`<article class="shop-card"><span class="big-icon">${f.icon}</span><h3>${f.name}</h3><p>${f.desc}</p><div class="stock-count">${state.stock[id].toFixed(1).replace('.0','')} <small style="font:11px var(--sans)">份在库</small></div><button data-action="buy" data-id="${id}" ${f.day>state.day||state.cash<f.cost*4?'disabled':''}>${f.day>state.day?'第 '+f.day+' 天解锁':'补 4 份 · '+money(f.cost*4)}</button></article>`).join('')}</div>`;modal('菜篮子要装满','采购本 · 买得刚刚好',body,'stock',`<div class="modal-footer"><p>金币不会随现实时间变化。关掉游戏，街坊就等你回来。</p><button class="primary" data-action="restock">常用四样各补 4 份 · ¥108</button></div>`);}
function upgradesModal(){if(state.challenge)return toast('挑战保持固定设施，返回小店后可以扩建。');modal('把小店拾掇起来','赚到的钱，变成看得见的成长',`<p class="modal-intro">现金 ${money(state.cash)}。员工与设施在开门前或打烊后安排；购买后永久生效。</p><button class="wide" data-action="crew">伙计分工与培养 →</button><div class="upgrade-grid">${Object.entries(E.UP).map(([id,u])=>`<article class="upgrade-card"><h3>${u.name}</h3><p>${u.desc}</p><footer><strong>${money(u.cost)}</strong><button data-action="upgrade-buy" data-id="${id}" ${state.upgrades[id]||u.day>state.day||state.cash<u.cost||state.phase==='service'?'disabled':''}>${state.upgrades[id]?'✓ 已安排':u.day>state.day?'第 '+u.day+' 天解锁':state.phase==='service'?'打烊后安排':'安排上'}</button></footer></article>`).join('')}</div>`,'upgrade');}
function catsModal(){
 const tables=state.tables.filter(t=>['waiting','eating'].includes(t.status)&&!t.petCount);
 modal('三位猫掌柜','一次安排，持续陪一桌',`<div class="cat-grid">${state.cats.map((c,i)=>`<article class="cat-profile">${catSprite(i)}<h3>${c.name} · ${E.CAT_ROLES[i].role}</h3><p>${E.CAT_ROLES[i].desc}</p><span class="bond">亲近度 ${c.bond} / 40 · ${c.bond>=40?'已学会按分工自动帮忙':'再熟一点，会主动帮忙'}</span><p class="cat-status">${E.catStatus(state,i)}</p><div><select id="cat-table-${i}" aria-label="给${c.name}选择陪伴桌号">${tables.length?tables.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${t.id+1} 桌 · ${t.guest.name}${t.status==='waiting'?'（等餐中）':''}</option>`).join(''):'<option>这会儿没有需要陪伴的桌子</option>'}</select><button data-action="cat-assign" data-id="${i}" ${!tables.length||c.cd>0||c.remaining>0?'disabled':''}>安排陪伴 ${E.CAT_ROLES[i].duration} 秒</button>${c.bond>=40?`<button data-action="cat-auto" data-id="${i}" aria-pressed="${c.auto}">${c.auto?'✓ 自动帮忙已开启':'开启自动帮忙'}</button>`:''}</div></article>`).join('')}</div><p class="modal-intro">每桌安排一次，每只猫同时陪一桌。油碟陪满 24 秒才有合影；亲近度 40 后还会带来猫粉预约。糍粑让等餐的人更有耐心，但电影不会因此推迟。煤球适合窗边与安静客人。猫咪增加心情、小费和回访意愿，餐食需求单独结算。</p>`,'cats');
}
function regularsModal(){
 const relationships=Object.values(state.city.relationships).map(r=>`<article class="city-card"><span class="event-label">拼桌关系 · 已解锁联合预约</span><h3>${esc(r.name)}</h3><p>第 ${r.day} 天在本店相识，之后会约好一起来。</p></article>`).join('');
 const chains={luo:['悄悄留清汤','带朋友也有面子','获赠江湖蘸碟'],solo:['一人好好吃','带朋友安静聚聚','固定窗边预约']};
 modal('一条街，慢慢养熟','好好招待，下一次会不一样',`<div class="city-grid">${relationships}</div><div class="story-grid">${E.G.map(g=>{const r=state.regulars[g.id],step=E.storyStep(state,g.id);return `<article class="story-card">${person(C.lead(g))}<div><h3>${g.who}</h3><small>${r?'来过 '+r.visits+' 回 · 回访意愿 '+(r.returnInterest||0):'还在来店的路上'}</small><p>${esc(r?.memory||g.quote)}</p>${chains[g.id]?`<ol class="story-steps">${chains[g.id].map((text,i)=>`<li class="${i<step?'done':''}">${i<step?'✓':i+1} ${text}</li>`).join('')}</ol><small>每个营业日最多推进一回；基本需求满足、餐食评价 80+。</small>`:''}</div></article>`;}).join('')}</div><div class="badge-row">${state.badges.map(b=>`<span class="badge">${b}</span>`).join('')}</div>`,'regulars');
}
function eventsModal(){modal('老街每天有新鲜事','真实新闻的经营启发 · 原创人物与剧情',`<p class="modal-intro">七天后继续轮换：雨夜热汤、毕业饭、末班车、猫掌柜见面会、戏班返场和街坊聚会。今天是「${E.event(state).name}」：${E.event(state).goal}。</p><div class="event-list">${E.EVENTS.map((e,i)=>`<article class="event-card ${i===state.day-1?'current':''}"><span class="event-day">0${i+1}</span><div><h3>${e.name} ${state.badges.includes(e.badge)?'✓':''}</h3><p>${e.story}</p><p><b>目标：</b>${e.goal}</p><span class="event-reward">奖励 ${money(e.reward)} ＋「${e.badge}」＋ ${E.rewardText(i+1)}</span><p>${e.modes.map(m=>m[1]+'：'+m[2]).join(' / ')}</p><small>创作灵感：${e.source}</small></div></article>`).join('')}</div><p class="modal-intro">新闻是设计灵感，关卡数值、人物和事件均为原创。资料见随游戏提供的《事件设计与新闻来源》。</p>`,'events');}
function recipeModal(){modal('一锅传一锅的招牌','好搭配存下来，小满就能照着做',`<p class="modal-intro">配锅时可以保存自己的套餐；聘请跑堂后，小满会从保存套餐与基础方案中选出符合预算、库存和口味的一份。最多保存 6 份。</p><button class="primary wide" data-action="research">试锅研发 · 做出独家招牌 →</button><div class="city-grid">${signatureCards()}</div>${state.recipes.length?state.recipes.map((r,i)=>`<article class="recipe-card"><div><strong>${esc(r.name)}</strong><p>${E.P[r.plan.pot].name} · ${r.plan.broths.map(id=>E.B[id].name).join(' / ')}<br>${r.plan.rounds.filter(r=>r.length).map(r=>r.map(id=>E.F[id].short).join('＋')).join(' → ')}${r.plan.small?' · 小份':''}</p></div><button data-action="delete-recipe" data-id="${i}">移出菜单</button></article>`).join(''):'<div class="empty-message">第一份招牌还在你的汤勺里。<br>给客人配锅时，起个名字，再点「存为招牌」。</div>'}`,'recipes');}
function insight(a){let poor=a.records.filter(r=>r.score<80);if(a.stockLost)return `有 ${a.stockLost} 桌因为缺货没能开锅。小满再勤快也不能变出食材；明天按预约补好菜，营业时也能暂停补货。`;if(a.lost)return `有 ${a.lost} 桌等得太久离开。${state.upgrades.staff?'已有跑堂也要检查套餐是否合适，或亲自给这桌配锅。':'明天试试跑堂小满，或更早替客人配锅。'}`;if(poor.length)return `「${poor[0].guest}」得到 ${poor[0].score} 分。${poor[0].reasons.find(r=>/没有|偏少|耽误|遗憾|等位/.test(r))||'先菌菇、后肉菜、再吸汁豆腐，可以再试一次。'}`;if(a.waste)return `多囤的食材报损了 ${money(a.waste)}。明天照着预约买，留一点周转余量就好。`;return '先养汤、再下吸味菜的搭配很受欢迎。试着把它存成招牌，让小满也能做出同样的味道。';}
function settlementModal(){if(state.phase!=='settlement')return;if(state.challenge)return challengeResult();let a=state.stats,final=state.day===7;modal(final?'一街人，记得这一锅':'打烊了，翻翻今天的账','第 '+state.day+' 天 · '+E.event(state).name,`${final?'<div class="badge-title">七天的烟火，养熟了一条街。</div>':''}<div class="receipt-grid"><section class="ledger-sheet"><h3>今天赚到了什么</h3>${[['餐费收入',a.revenue],['客人小费',a.tips],['已用食材',-a.food],['锅底成本',-a.pots],['演出、服务与人情支出',-a.expense],['库存报损',-a.waste],['当日工钱与杂费',-a.wages]].map(([n,v])=>`<div class="ledger-line"><span>${n}</span><strong>${v<0?'− ':''}${money(Math.abs(v))}</strong></div>`).join('')}<div class="ledger-line total"><span>营业净收益</span><strong>${money(a.profit)}</strong></div><div class="ledger-line"><span>事件奖金（另外入账）</span><strong>＋${money(a.reward)}</strong></div><div class="ledger-line"><span>手头现金（采购、设施另计）</span><strong>${money(state.cash)}</strong></div><div class="goal-reward"><b>${a.goal?'✓ 小目标达成':'明天还有好锅'}</b><small>${a.goal?'收下「'+E.event(state).badge+'」纪念章<br>'+E.rewardText(state.day):'差一点也没关系，街坊还会来。'}</small></div></section><section><h3 class="section-title">每一桌都留了句话</h3>${a.records.map((r,i)=>`<div class="result-row"><span>${r.guest}</span><strong>${r.essentialOk===false?'需求未满足':r.score+' 分'}</strong><button data-action="receipt" data-id="${i}">小票 ↗</button></div>`).join('')||'<div class="empty-message">今晚还没招待成一桌。下一锅再试。</div>'}<div class="story-rewards">${(a.storyRewards||[]).map(x=>`<p>✦ ${esc(x)}</p>`).join('')}</div><p class="insight">${insight(a)}</p><p class="mini-note">拼桌 ${a.shared||0} 次 · 最后一锅 ${a.lateServed||0} 份 · 加班工资 ¥${a.overtime||0}（已计入工钱）</p><div class="tomorrow"><small>${final?'梅嬢嬢的话':'明天老街的头条'}</small><h4>${final?'“锅会熄，人情不会。”':E.event({...state,day:state.day+1}).name}</h4><p>${final?'这七天的熟客、猫咪亲近度和招牌都会保留。还想开门，就继续把日子煮得热乎乎。':E.event({...state,day:state.day+1}).story}</p></div><div class="badge-row">${state.badges.map(b=>`<span class="badge">${b}</span>`).join('')}</div></section></div>`,'settlement',`<div class="modal-footer"><p>营业利润按消耗计算；采购和设施影响现金。<br>猫咪互动 ${a.pets} 次 · ${a.showFinished?'变脸看完 '+a.showWatched+' 桌':a.showDone?'变脸进行中':'今晚未演出'}</p><div class="buttons"><button data-action="modal-close">再看看小店</button><button class="primary" data-action="next">${final?'继续街坊日常':'明天开门'} →</button></div></div>`);}
function ledgerModal(){if(state.phase==='settlement')return settlementModal();let body=`<p class="modal-intro">现金 ${money(state.cash)} · 街坊口碑 ${state.rep} · ${Object.values(state.regulars).reduce((a,r)=>a+r.visits,0)} 桌来过。</p>${state.history.length?state.history.map(h=>`<div class="ledger-line"><span>第 ${h.day} 天 · ${h.served} 桌${h.goal?' · 事件完成':''}</span><strong>${money(h.profit)}</strong></div>`).join(''):'<div class="empty-message">账本的第一页，等你写下第一锅。</div>'}${state.stats?`<p class="insight">今晚已收餐费 ${money(state.stats.revenue)}，小费 ${money(state.stats.tips)}；${state.stats.served} 桌离店。</p>`:''}`;modal('梅嬢嬢的账本','一笔钱，一点人情',body,'ledger');}
function receiptModal(id){let r=state.stats?.records[id];if(!r)return;modal('本桌小票','一锅江湖 · 带走一份山城味',`<div class="ledger-sheet" style="max-width:480px;margin:auto"><h3>${r.guest}</h3><div class="ledger-line"><span>第 ${state.day} 天 · ${E.P[r.pot].name}</span><strong>${r.score} 分</strong></div>${r.rounds.map((round,i)=>`<div class="ledger-line"><span>第 ${i+1} 轮</span><strong>${round.map(id=>E.F[id].short).join('、')}</strong></div>`).join('')}<div class="ledger-line"><span>餐费 ＋ 小费</span><strong>${money(r.price+r.tips)}</strong></div><p class="insight">“${esc(r.quote)}”</p><p class="receipt-outcome">基本需求：${r.essentialOk===false?'未满足':'已满足'} · 额外心情 ${r.mood||0}${r.wishes?.birthday?' · 生日惊喜完成':''}${r.wishes?.photo?' · 合影心愿完成':''}</p><div class="eval-reasons">${r.reasons.map(x=>'✓ '+esc(x)).join('<br>')}</div></div>`,'receipt',`<div class="modal-footer"><p>每张小票都是你的经营选择留下的结果。</p><button class="primary" data-action="download-receipt" data-id="${id}">把小票带走 ↓</button></div>`);}
function helpModal(){modal('来嘛，先吃一锅。','一锅江湖 · 山城怪趣七日试玩',`<div class="help-hero"><img src="assets/auntie.png" alt="包租婆梅嬢嬢"><div><h3>配好一锅，招待一桌，<br>养熟一条街。</h3><p>你是嘴硬心软的梅嬢嬢。四张桌、三只猫、一口大茶壶。<br>从第一桌街坊开张，到第七天办一场老街开锅节。</p></div></div><div class="help-grid"><article class="help-card"><h3>① 读懂一桌人的心</h3><p>点击桌子，看口味、预算和时间。单锅快，鸳鸯锅照顾不同人。配餐时全店暂停，可以慢慢想。</p></article><article class="help-card"><h3>② 让汤越涮越香</h3><p>每桌最多三轮，每轮两盘。菌菇先养鲜，肉菜带浓香，豆腐吸味收尾。急客少一轮，生日最后上糍粑。</p></article><article class="help-card"><h3>③ 猫咪与变脸</h3><p>油碟陪合影、糍粑安抚等餐、煤球陪安静客人。第 2 天可排短场或压轴变脸，打拍可跳过。开心会增加小费，赶电影的时间仍要守住。</p></article><article class="help-card"><h3>④ 把日子煮得更好</h3><p>每天一个新闻启发的原创事件。备货、存套餐、聘跑堂、扩桌。打烊账本解释结果，熟客记住上一锅。</p></article></div><p class="modal-intro">右上角 ♪ 打开「江湖留声机」，分别调整音乐、音效、环境声音。操作：鼠标 / 触控。空格暂停，1—4 选桌，Esc 关闭面板。营业时可 1× / 2× / 3× 加速。进度保存在当前浏览器；离开页面会自动暂停，不计算离线损失。七天后可继续经营。</p>`,'help',`<div class="modal-footer"><button data-action="reset-confirm">重新开一家店</button><button class="primary" data-action="modal-close">好，晓得了 →</button></div>`);}
function showModal(){
 if(state.day<2)return modal('师傅在后台练绝活','第二天起可以排正式演出',`<p class="modal-intro">先看一段 8 秒变脸动画。正式演出从第二天起开放，可安排短场和压轴场。</p><button class="primary wide" data-action="cinema">▶ 先看一场变脸动画</button>`,'show');
 if(state.phase==='settlement')return toast('师傅也收工啦，明天开门前来排场次。');
 if(state.stats?.showDone)return modal('今晚的锅边好戏','客人吃饭，师傅照常演出',`<p class="modal-intro">${state.stats.showRemaining>0?'正在演出，还剩 '+Math.ceil(state.stats.showRemaining)+' 秒。关闭面板并继续营业，演出才会继续。':'已经谢幕，'+state.stats.showWatched+' 桌看完。明天再约师傅。'}</p><button class="primary wide" data-action="cinema">▶ 看变脸动画</button>`,'show');
 const type=state.showPlan.type;opera={running:false,hits:0,round:0,start:0,result:[]};
 modal('锅边好戏 · 排场次','短场赶得上，压轴看尽兴',`<button class="wide" data-action="cinema">▶ 看师傅的 8 秒变脸绝活</button><div class="show-layout"><img class="show-portrait" src="assets/performer.png" alt="川剧变脸师傅"><section><div class="show-types">${[['short','十秒短场','轻巧开场，安静桌也自在'],['finale','二十秒压轴','游客更尽兴，安静客人要靠窗']].map(([id,name,desc])=>`<button class="${type===id?'active':''}" data-action="show-type" data-id="${id}"><strong>${name} · ¥${E.showFee(state,id)}</strong><small>${desc}</small></button>`).join('')}</div><p class="mini-note">演出与吃饭同时进行；看完才有心情加成。不会改变口味和行程是否达标。</p><label class="schedule-row">开门后何时登台<select id="show-time"><option value="manual" ${state.showPlan.at===null?'selected':''}>我来喊开场</option>${[45,75,110].filter(n=>state.phase==='prep'||n>state.elapsed).map(n=>`<option value="${n}" ${state.showPlan.at===n?'selected':''}>第 ${n} 秒</option>`).join('')}</select></label><button data-action="show-schedule">保存场次安排</button><h3 class="section-title">现在开演，会影响谁？</h3><div class="show-audience">${E.showPreview(state,type).map(a=>`<p class="${a.benefit<0?'unmet':''}"><b>${a.id+1} 桌 · ${a.name}</b><span>${a.note} · 心情 ${a.benefit>0?'+':''}${a.benefit}</span></p>`).join('')||'<p>客人还没入座。开门后这里会显示各桌的受益和影响。</p>'}</div></section></div>`,'show',`<div class="modal-footer"><p>打拍是可选加成，每拍额外 +1 心情。<br>${state.showPlan.at!==null?'已约好第 '+state.showPlan.at+' 秒登台':'当前为手动开场'}</p><div class="buttons"><button data-action="opera-rhythm" ${state.phase!=='service'?'disabled':''}>我来打三拍</button><button class="primary" data-action="opera-normal" ${state.phase!=='service'||state.cash<E.showFee(state)?'disabled':''}>直接开演 · ¥${E.showFee(state)}</button></div></div>`);
}
function startOpera(){if(!opera||opera.running)return;opera.running=true;opera.start=performance.now();opera.round=0;opera.hits=0;opera.result=[];opera.lastCycle=0;syncSound();$('#opera-play').innerHTML=`<div class="beat-target" id="beat-target">第一变 · 红袍开场</div><div class="rhythm-track"><span class="rhythm-zone"></span><span class="rhythm-pin" id="rhythm-pin"></span></div><div class="rhythm-labels"><span>听鼓</span><span>绿色区域 · 亮相！</span><span>等下一圈</span></div><button class="primary wide" data-action="opera-hit">亮相！ <small>点击 / 空格</small></button><p class="mini-note" id="beat-feedback">想好再出手，没有倒计时惩罚。</p>`;chime('opera-start');}
function operaHit(){if(!opera?.running)return;let progress=((performance.now()-opera.start)%2200)/2200,hit=progress>=.36&&progress<=.64;opera.result.push(hit);if(hit)opera.hits++;opera.round++;chime(hit?'opera-hit':'opera-miss');$('#opera-art').classList.remove('flipping');void $('#opera-art').offsetWidth;$('#opera-art').classList.add('flipping');$('#opera-art').style.setProperty('--face',['#bb3c2c','#387883','#d6a849'][opera.round-1]);$('#beat-count').innerHTML=[0,1,2].map((i)=>`<span class="${i<opera.round?(opera.result[i]?'hit':'miss'):''}">${i<opera.round?(opera.result[i]?'✓':'·'):i+1}</span>`).join('');if(opera.round>=3){opera.running=false;syncSound();E.show(state,opera.hits);if(opera.hits===3)chime('fanfare');$('#opera-play').innerHTML=`<div class="opera-score">${opera.hits} / 3 拍 · ${opera.hits===3?'满堂彩！':opera.hits===2?'好身手！':'初登台也精彩'}</div><p class="opera-instructions">${opera.hits===3?'红袍一甩，金面登场。收下「三连绝活」纪念章！':'师傅鞠躬谢幕，客人举起筷子叫好。明天再练这门绝活。'}<br>演出现在开始。看完整场的客人额外获得 ${opera.hits} 点心情，餐食评价单独结算。关闭面板，继续营业即可看完演出。</p><button class="primary wide" data-action="cinema">▶ 看变脸动画，听声叫好</button><button class="wide" data-action="modal-close">喝彩收好，继续开锅 →</button>`;save();render();}else{$('#beat-target').textContent=['','第二变 · 青面亮相','第三变 · 金面压轴'][opera.round];$('#beat-feedback').textContent=hit?'这一拍准了，客人拍桌叫好！':'稍微错了一拍，下一变再来。';opera.start=performance.now();opera.lastCycle=0;}}
function seatModal(){const t=state.tables[selected];if(!t||!['waiting','eating'].includes(t.status))return toast('先选一桌客人，再安排座位。');modal('给这桌找个合适位置',t.guest.name,`<p class="modal-intro">现在坐在 ${selected+1} 桌 · ${E.seatName(t.seat)}。吧台适合快涮，窗边隔开戏台，六人团圆局需要长桌。</p><div class="seat-options">${state.tables.map(x=>{const type=E.seatType(state,x.id,state.tables.length);return `<button data-action="move-seat" data-id="${x.id}" ${x.status!=='empty'||E.capacity(type)<t.guest.size?'disabled':''}><strong>${x.id+1} 桌 · ${E.seatName(type)}</strong><small>${E.capacity(type)} 人位 · ${x.status==='empty'?'空桌':'正在使用'}</small></button>`;}).join('')}</div>`,'seats');}
function rhythmModal(){if(state.cash<E.showFee(state))return toast('演出费暂时不够，先招待一桌吧。');opera={running:false,hits:0,round:0,result:[]};modal('嬢嬢来打三拍','不打拍也能正常演出',`<div class="opera-layout"><div class="opera-art" id="opera-art"><img src="assets/performer.png" alt="川剧师傅"><div class="opera-face"></div></div><section><div class="beat-count" id="beat-count"><span>1</span><span>2</span><span>3</span></div><div id="opera-play"></div></section></div>`,'show');startOpera();}
let ownerTimer,ownerLine=0;
const OWNER_LINES=['吃饭莫慌，锅里有汤，嬢嬢有办法。','哪个说清汤没江湖？吃得舒服才算数！','猫掌柜只陪吃，不替你赶电影哈。','钱可以慢慢赚，糍粑要趁热吃！'];
function ownerAct(kind='hello',line){
 const text=line||OWNER_LINES[ownerLine++%OWNER_LINES.length];
 $$('.owner-character,.host-portrait,.nav-owner').forEach(el=>{el.classList.remove('owner-hello','owner-serve','owner-clean','owner-cheer','owner-tea');void el.offsetWidth;el.classList.add('owner-'+kind);});
 $('#owner-quote').textContent=text;const speech=$('#host-speech');if(speech)speech.textContent=text;
 clearTimeout(ownerTimer);ownerTimer=setTimeout(()=>$$('.owner-character,.host-portrait,.nav-owner').forEach(el=>el.classList.remove('owner-'+kind)),2400);
 if(!$('#modal').open)toast('梅嬢嬢：'+text);
}
function ownerModal(){
 const occupied=state.tables.filter(t=>['waiting','eating'].includes(t.status)).length,canTea=state.phase==='service'&&!state.stats?.teaServed&&occupied>0&&state.cash>=8;
 modal('梅嬢嬢当班','嘴硬心软，照顾人的手脚最麻利',`<div class="host-scene"><img class="host-portrait" src="assets/auntie.png" alt="举着汤勺的梅嬢嬢"><div class="host-bubble" id="host-speech">${OWNER_LINES[ownerLine++%OWNER_LINES.length]}</div><span class="host-steam">∿ ∿</span></div><div class="host-options"><button data-action="owner-talk">嬢嬢，招呼一声！</button><button class="primary" data-action="owner-tea" ${canTea?'':'disabled'}>${state.stats?.teaServed?'今天已经请过茶':'请在座街坊喝茶 · ¥8'}</button></div><p class="mini-note">一壶茶照顾在座的 ${occupied} 桌：心情 +3，等餐客人耐心 +12 秒。每天一次，不改变电影限时。开锅、收台、结账时，嬢嬢也会挥勺忙活或开心庆祝。</p>`,'owner',`<div class="modal-footer"><button data-action="more">账本与更多事情</button><button class="primary" data-action="modal-close">回店里照看 →</button></div>`);
 ownerAct('hello');chime();
}

/* The street is a single menu on narrow screens. */
function cityModal(){
 const n=state.city,offers=E.favorOffer(state),relations=Object.keys(n.relationships).length;
 modal('街坊江湖','把故事养熟，把手艺留下',`<p class="modal-intro">${state.challenge?'正在独立挑战，正常小店已完整暂存。':`本店已有 ${n.dishes.length} 道研发招牌、${relations} 段拼桌关系。每次选择都留在下一天。`}</p><div class="city-grid">${[
 ['pair','凑一桌，交个朋友','看共同爱好，再决定谁和谁坐'],['research','试一锅本店招牌','食材 × 做法 × 蘸料，让熟客试吃'],['favors','梅嬢嬢的人情账',offers?'今天街坊有事想请你搭把手':'看看预约回信与生日助演'],['crew','我的老街班底','分工到桌，熟练后接手重点饭局'],['late','收摊前的最后一锅',n.last.state==='offered'?'现在可售！用余料留一盏灯':'第三天起，招待完预约后限量开卖'],['challenges','街坊怪挑战','三个固定题目，失败不影响小店'],['regulars','熟客与饭搭子',relations+' 段关系，老罗与阿青的老位置'],['cinema','看一场川剧变脸','8 秒独立动画 · 红、青、金面亮相']
 ].map(([id,title,desc])=>`<button data-action="${id}"><strong>${title}</strong><small>${desc}</small></button>`).join('')}</div>${state.challenge?'<button class="wide" data-action="challenge-exit">收好挑战，回正常小店 →</button>':''}`,'city');
}
function renderCity(){
 const btn=$('.bottom-bar [data-action="city"]');if(btn){const alert=state.city.last.state==='offered'||!!E.pending(state)||state.tables.some(t=>t.pairOffer&&t.status==='waiting');btn.classList.toggle('has-news',alert);btn.setAttribute('aria-label','街坊江湖'+(alert?'，有待处理的饭局':''));}
 if(state.challenge){$('#day-label').textContent='怪挑战 · '+state.challenge.code;$('#scene-hint').textContent='挑战采用固定库存，随时从街坊江湖返回正常小店。';const goal=$('#objective .event-link');if(goal){goal.dataset.action='challenges';goal.textContent='查看挑战 / 返回小店 ↗';}}
 if(state.city.last.state==='offered'&&!state.city.last.notified&&!$('#modal').open){state.city.last.notified=true;setTimeout(()=>{if(state.city.last.state==='offered'&&!$('#modal').open)lateModal();},0);}
}
let pairSource=null,pairTarget=null;
function pairModal(){
 const waiting=state.tables.filter(t=>t.status==='waiting'&&!t.parties),queue=E.pending(state),sources=waiting.map(t=>({id:String(t.id),name:(t.id+1)+' 桌 · '+t.guest.name,g:t.guest}));
 if(queue)sources.push({id:'queue',name:'门口等位 · '+queue.guest.name,g:queue.guest});
 if(!sources.some(s=>s.id===pairSource))pairSource=sources[0]?.id||null;
 const targets=waiting.filter(t=>String(t.id)!==pairSource);
 if(!targets.some(t=>t.id===pairTarget))pairTarget=targets[0]?.id??null;
 const preview=pairSource!==null&&pairTarget!==null?E.pairPreview(state,pairSource,pairTarget):null;
 modal('拼桌江湖','还没开锅时，问一句愿不愿意',`<p class="modal-intro">不愿拼桌的安静客人会明确拒绝。两组共同按人数分摊，锅底、份量、预算和行程都要照顾到。</p>${sources.length?`<div class="city-form"><label>让哪一组加入<select id="pair-source">${sources.map(x=>`<option value="${x.id}" ${x.id===pairSource?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>坐到哪一桌<select id="pair-target">${targets.map(t=>`<option value="${t.id}" ${t.id===pairTarget?'selected':''}>${t.id+1} 桌 · ${esc(t.guest.name)}</option>`).join('')||'<option value="">没有可接桌的客人</option>'}</select></label></div><div class="city-clues">${sources.filter(x=>x.id===pairSource||x.id===String(pairTarget)).map(x=>`<p><b>${esc(x.name)}</b><span>${E.clue(x.g).note} · ${x.g.size} 人 / ¥${x.g.budget}</span></p>`).join('')}</div>${preview?`<p class="${preview.errors.length?'eval-warning':'insight'}">${preview.errors.length?preview.errors.join('；'):preview.description+'。合计 '+preview.group.size+' 人，整桌预算 ¥'+preview.group.budget+'。'}</p><button class="primary wide" data-action="pair-confirm" ${preview.errors.length?'disabled':''}>问好两边，安排同桌 →</button>`:''}`:'<div class="empty-message">开门后，两组客人还没开锅时可以拼桌。<br>第 4 天，严师傅和想学川剧的同学会来。</div>'}<div class="city-list">${state.tables.filter(t=>t.shared?.clash&&!t.shared.mediated&&t.status==='waiting').map(t=>`<article><strong>${t.id+1} 桌 · 聊天撞上赶时间</strong><p>请茶 ¥5，把额外延时从 8 秒降到 2 秒。</p><button data-action="mediate" data-id="${t.id}">嬢嬢出面调解</button></article>`).join('')}</div>`,'pair');
}
let researchDraft={base:'tofu',method:'roast',sauce:'oil',taster:'luo'};
function signatureCards(){return state.city.dishes.map(d=>`<article class="city-card"><span class="event-label">${state.city.featured===d.id?'今日主打 · ':''}已卖 ${d.sold} 桌</span><h3>${esc(d.name)}</h3><p>${E.F[d.base].name} · ${E.dishDescription(d)}</p><label class="city-rename">自己的菜名<input id="dish-name-${d.id}" maxlength="12" value="${esc(d.name)}"></label><div class="city-actions"><button data-action="dish-rename" data-id="${d.id}">改名</button><button data-action="dish-feature" data-id="${d.id}" ${state.phase!=='prep'||state.challenge?'disabled':''}>挂主打</button><button data-action="dish-poster" data-id="${d.id}">菜单海报 ↗</button></div></article>`).join('');}
function researchModal(){
 const n=state.city,used=n.researchDay===state.day;
 modal('试锅研发所','一间店，总要有别人学不来的味道',`<p class="modal-intro">每天开门前试一次，花 ¥6 与半份主食材。先听试吃人的偏好再搭配：老罗爱红油、阿青爱清香、同学想尝迷你三拼。成功的招牌可在配锅时选用，明天主打会吸引专程来点菜的人。</p>${!state.challenge?`<div class="city-form"><label>主食材<select id="research-base">${E.unlocked(state).map(id=>`<option value="${id}" ${researchDraft.base===id?'selected':''}>${E.F[id].name}</option>`).join('')}</select></label><label>处理方式<select id="research-method">${Object.entries(E.METHODS).map(([id,x])=>`<option value="${id}" ${researchDraft.method===id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>蘸料<select id="research-sauce">${Object.entries(E.SAUCES).map(([id,x])=>`<option value="${id}" ${researchDraft.sauce===id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>请谁试吃<select id="research-taster">${[['luo','老罗 · 喜欢红油香碟'],['solo','阿青 · 想吃芝麻清香碟'],['student','同学 · 想尝迷你三拼']].map(([id,name])=>`<option value="${id}" ${researchDraft.taster===id?'selected':''}>${name}</option>`).join('')}</select></label></div><p class="mini-note">先烤后涮：多 6 秒、多卖 ¥4，多用 ¥2 处理费。迷你三拼：菌菇、豆腐、莴笋各 0.35 份，快 3 秒、少卖 ¥2。蘸料另计 ¥1。</p><button class="primary wide" data-action="research-try" ${state.phase!=='prep'||used?'disabled':''}>${used?'今天试过了，明天再试':state.phase!=='prep'?'开门前再来试锅':'试这一锅 · ¥6 ＋ 半份食材'}</button>`:'<p class="insight">挑战只用固定食材和配方。回正常小店后可研发。</p>'}${n.lastResearch?.day===state.day?`<p class="insight">试吃回话：${esc(n.lastResearch.feedback)}</p>`:''}<h3 class="section-title">本店研发招牌</h3><div class="city-grid">${signatureCards()||'<p>第一道独家招牌，还等你试出来。</p>'}</div>`,'research');
}
function favorModal(){const n=state.city,f=E.favorOffer(state);modal('梅嬢嬢的人情账','帮忙有代价，回信有日子',`${f?`<article class="city-card"><h3>${f.name}</h3><p>${f.story}</p><div class="city-actions"><button class="primary" data-action="favor-choice" data-id="help">${f.id==='courier'?'借一号桌热饭':'借出跑堂'}</button><button data-action="favor-choice" data-id="alternative">${f.id==='courier'?'送热汤 · ¥6':'送一份糍粑'}</button><button data-action="favor-choice" data-id="decline">今天忙不过来</button></div></article>`:`<p class="modal-intro">${state.day<2?'第二天起，街坊会来请你搭把手。':'今天的请求已记好。没有每天必做的帮忙，店忙可以拒绝。'}</p>`}<p class="insight">冰粉摊生日助演：${n.sweetHelp||0} 次。${state.phase==='service'?'<button data-action="birthday-help">给当前生日桌安排</button>':''}</p><div class="city-list">${n.favors.slice().reverse().map(f=>`<article><b>第 ${f.day} 天 · ${f.id==='courier'?'快递小哥':'对门冰粉摊'}</b><p>${f.choice==='decline'?'说好下次再帮':f.delivered?'回信已兑现':`第 ${f.due} 天开门时兑现${f.id==='courier'?'同事预约':'生日助演'}`}</p></article>`).join('')||'<p>人情本还空着，慢慢来。</p>'}</div>`,'favors');}
function crewModal(){const n=state.city;modal('我的老街班底','以前嬢嬢救场，现在有人搭手',`<p class="modal-intro">首位伙计 ¥160，后续每人 ¥100。首位工钱 ¥20 / 天，后续每人 ¥16 / 天。未分配的桌由首位照顾；招待成功 3 桌后学会本行的特殊饭局。当前${n.borrowUntil>state.elapsed?'借给冰粉摊帮忙，暂时停止自动接单':'正常当班'}。</p><div class="city-grid">${Object.entries(E.CREW).map(([id,x])=>{const c=n.crew.find(c=>c.id===id);return `<article class="city-card"><h3>${x.name} · ${x.title}</h3><p>${x.desc}</p>${c?`<span class="bond">熟练度 ${c.xp} · ${c.xp>=3?'拿手饭局已学会':'再招待 '+(3-c.xp)+' 桌就学会'}</span><div class="city-actions">${Array.from({length:state.upgrades.tables?6:4},(_,i)=>`<button data-action="crew-assign" data-id="${id},${i}" class="${E.worker(state,i)?.id===id?'active':''}" aria-pressed="${E.worker(state,i)?.id===id}">${i+1} 桌</button>`).join('')}</div>`:`<button data-action="crew-hire" data-id="${id}" ${state.challenge||state.phase==='service'||state.day<2?'disabled':''}>${state.day<2?'第二天可聘请':'聘请 · ¥'+(state.upgrades.staff?100:160)}</button>`}</article>`;}).join('')}</div>`,'crew');}
function lateModal(){const n=state.city,offered=n.last.state==='offered';modal('最后一锅，留盏灯','“还有三份，吃完嬢嬢就收摊！”',`<p class="modal-intro">${offered?'预约都招待完了，看看库存再决定。面板打开时营业暂停，可以慢慢算。':'第三天起，当所有预约吃完、桌子收好后出现。可以主动结束，也可以把余料卖成一锅热汤。'}</p><div class="city-grid">${E.lateOptions(state).map(x=>`<article class="city-card"><h3>${x.name}</h3><p>${x.plan.rounds.flat().map(id=>E.F[id].short).join(' ＋ ')}<br>每份餐费 ¥${x.m.price}，菜锅成本 ¥${x.m.cost}，加班工钱 ¥6。<br>每份用餐 ${x.m.duration} 秒，库存最多可做 ${x.max} 份。</p><label>限量份数<select id="late-count-${x.id}">${[1,2,3].map(i=>`<option value="${i}" ${i>x.max?'disabled':''}>${i} 份</option>`).join('')}</select></label><button class="primary wide" data-action="late-sell" data-id="${x.id}" ${!offered||!x.max||x.m.errors.length?'disabled':''}>留一锅热的 →</button></article>`).join('')}</div><p class="mini-note">最多 3 份，间隔 12 秒到店，提前明确增加的工钱；食材和锅底照常消耗。最后一锅会自动开涮。</p>${offered?'<button class="wide" data-action="late-skip">今天收工，明天再开锅</button>':`<p class="insight">${n.last.state==='running'?'限量锅已开卖，招待完自动结账。':n.last.state==='skipped'?'今天已经收好最后一锅。':'等晚归街坊来。'}</p>`}`,'late');}
function challengesModal(){modal('街坊怪挑战','同一道题，看看你的招待办法',`<p class="modal-intro">三道题都用固定客人、库存和 ¥400 初始现金。不能采购、扩店或研发，失败也不会损失正常存档。尝试不同锅型和上菜顺序，最后生成方案小票。</p><div class="city-grid">${E.CHALLENGES.map(c=>{const b=state.city.challengeBest[c.id];return `<article class="city-card"><span class="event-label">${c.code}</span><h3>${c.name}</h3><p>${c.desc}</p>${b?`<small>个人记录：${b.won?'已完成 · '+b.seconds+' 秒':'尝试过，再来一锅'}</small>`:''}<button class="primary wide" data-action="challenge-start" data-id="${c.id}" ${state.challenge?'disabled':''}>接受这个题目 →</button></article>`;}).join('')}</div>${state.challenge?'<button class="wide" data-action="challenge-exit">结束本次挑战，恢复正常小店</button>':''}`,'challenges');}
function challengeResult(){const a=state.stats;modal(a.goal?'这道题，招待得漂亮！':'这锅还有另一种解法',state.challenge.code+' · '+state.challenge.name,`<p class="insight">${state.challenge.desc}</p><div class="city-score"><b>${a.goal?'挑战成功':'再试一次'}</b><span>${Math.ceil(state.elapsed)} 秒 · 招待 ${a.served} 组 · 拼桌 ${a.shared} 次 · 流失 ${a.lost} 组</span></div>${a.records.map((r,i)=>`<div class="result-row"><span>${esc(r.guest)}</span><strong>${r.essentialOk?'需求满足':'需求未满足'} · ${r.score}</strong><button data-action="receipt" data-id="${i}">小票 ↗</button></div>`).join('')}<p class="mini-note">正常小店的钱、库存、猫咪和故事进度均保留。仅记录这道题的个人成绩。</p>`,'challenge-result',`<div class="modal-footer"><button data-action="challenge-poster">生成方案小票</button><button class="primary" data-action="challenge-exit">回正常小店 →</button></div>`);}
async function shareCard(title,subtitle,lines,kind){
 const canvas=document.createElement('canvas');canvas.width=720;const measure=document.createElement('canvas').getContext('2d');measure.font='27px sans-serif';const wrapped=[];
 lines.forEach(line=>{let row='';for(const char of String(line)){if(measure.measureText(row+char).width>580){wrapped.push(row);row='';}row+=char;}wrapped.push(row,'');});
 canvas.height=Math.max(960,340+wrapped.length*42);const c=canvas.getContext('2d');c.fillStyle='#f7edd6';c.fillRect(0,0,720,canvas.height);c.strokeStyle='#a23e29';c.lineWidth=5;c.strokeRect(25,25,670,canvas.height-50);c.fillStyle='#a23e29';c.font='bold 30px serif';c.fillText('一锅江湖 · 山城怪趣',62,92);c.font='bold 46px serif';c.fillText(title,62,170,590);c.font='24px sans-serif';c.fillText(subtitle,62,222,590);c.fillStyle='#493b2d';c.font='27px sans-serif';wrapped.forEach((line,i)=>c.fillText(line,62,295+i*42));c.fillStyle='#a23e29';c.font='24px serif';c.fillText('配好一锅，招待一桌，养熟一条街。',62,canvas.height-65);
 const data=canvas.toDataURL('image/png');modal(title,'我的小店，值得留一张',`<img class="share-poster" src="${data}" alt="${esc(title)}分享图片"><p class="mini-note">可以截图或长按图片保存；不会自动发到任何平台。</p>`,'poster',`<div class="modal-footer"><a class="button primary" href="${data}" download="一锅江湖-${kind}.png">下载图片 ↓</a><button data-action="save-poster">保存到相册</button></div>`);
}
async function savePoster(){const data=$('.share-poster')?.src,api=window.xhs?.miniTool;if(!data)return;if(api?.writeTempFile&&api?.saveImageToPhotosAlbum){try{const f=await api.writeTempFile({data});await api.saveImageToPhotosAlbum({filePath:f.filePath});toast('图片已存到相册');return;}catch{toast('相册暂未保存成功，可以长按或截图留念。');}}else toast('浏览器可点下载图片，手机也可长按图片保存。');}
function stopCinema(){const v=$('#opera-video');if(v){v.pause();v.removeAttribute('src');v.load();v.remove();}}
function cinemaModal(){
 modal('一甩袖，一张新面孔','锅边小戏台 · 8 秒川剧变脸',`<div class="cinema-stage"><video id="opera-video" src="assets/opera.mp4" poster="assets/performer.png" playsinline webkit-playsinline controls preload="metadata" aria-label="川剧变脸动画，红面、青面、金面亮相"></video></div><p id="cinema-status" class="mini-note" role="status">看戏时营业暂停，返回后继续招待客人。看动画不额外收费。</p><div class="city-actions cinema-buttons"><button data-action="cinema-play">从头再看</button><button data-action="cinema-mute">${sound.settings.muted?'开启舞台声音':'舞台静音'}</button><button class="primary" data-action="modal-close">回店里继续开锅 →</button></div>`,'cinema');
 const v=$('#opera-video');v.muted=sound.settings.muted;v.volume=sound.settings.effects;v.addEventListener('volumechange',()=>{if(v.isConnected&&$('[data-action="cinema-mute"]'))$('[data-action="cinema-mute"]').textContent=v.muted?'开启舞台声音':'舞台静音';});v.addEventListener('error',()=>{if(!v.isConnected)return;$('#cinema-status').textContent='动画暂未加载成功，点“从头再看”重试。营业进度已暂停保留。';});v.addEventListener('ended',()=>{if(!v.isConnected)return;$('#cinema-status').textContent='好戏收在这一亮相。回店里，锅还热着。';});v.play().catch(()=>{if(!v.isConnected)return;$('#cinema-status').textContent='点画面上的播放按钮即可观看，营业已暂停。';});
}
function neighborhoodAction(action,id){let msg;switch(action){
 case'city':cityModal();break;case'pair':pairModal();break;case'pair-confirm':msg=E.merge(state,pairSource,pairTarget);if(msg)toast(msg);else{selected=pairTarget;closeModal();toast('坐到一起啦！现在给两组人配一锅。');}break;
 case'mediate':msg=E.mediate(state,Number(id));if(msg)toast(msg);else pairModal();break;
 case'research':researchModal();break;case'research-try':{for(const k of ['base','method','sauce','taster'])researchDraft[k]=$('#research-'+k).value;const r=E.research(state,researchDraft);if(r.error)toast(r.error);else{researchModal();chime(r.ok?'fanfare':'tap');toast(r.feedback);}break;}
 case'dish-rename':msg=E.renameDish(state,id,$('#dish-name-'+id).value);if(msg)toast(msg);else researchModal();break;
 case'dish-feature':msg=E.feature(state,id);if(msg)toast(msg);else{researchModal();toast('今日主打挂好了，明天会有人专程来。');}break;
 case'dish-poster':{const d=state.city.dishes.find(d=>d.id===id);if(d)shareCard(d.name,'梅嬢嬢的小店 · 独家招牌',[E.F[d.base].name+' × '+E.METHODS[d.method].name+' × '+E.SAUCES[d.sauce].name,E.dishDescription(d),'试吃街坊：'+({luo:'老罗',solo:'阿青',student:'山城同学会'}[d.taster]),'已经招待 '+d.sold+' 桌，下一锅等你来。'],'招牌菜单');break;}
 case'favors':favorModal();break;case'favor-choice':msg=E.favor(state,id);if(msg)toast(msg);else favorModal();break;
 case'birthday-help':msg=E.birthdayHelp(state,selected);if(msg)toast(msg);else{favorModal();toast('对门来搭把手，生日惊喜安排好啦。');}break;
 case'crew':crewModal();break;case'crew-hire':msg=E.hire(state,id);if(msg)toast(msg);else{crewModal();chime('buy');}break;case'crew-assign':{const [who,table]=id.split(',');msg=E.assign(state,who,Number(table));if(msg)toast(msg);else crewModal();break;}
 case'late':lateModal();break;case'late-sell':msg=E.late(state,id,Number($('#late-count-'+id).value));if(msg)toast(msg);else{closeModal();paused=false;toast('最后这锅开卖！吃完嬢嬢就收摊。');}break;
 case'late-skip':E.late(state,'skip');closeModal();E.closeDay(state);if(state.phase==='settlement')settlementModal();break;
 case'challenges':challengesModal();break;case'challenge-retry':{const backup=state.careerSave,next=E.createChallenge(state.challenge.id);next.careerSave=backup;state=next;paused=false;selected=0;closeModal();toast('同样的题目，再试一种安排。');break;}case'challenge-start':{const fresh=E.startChallenge(state,id);if(fresh){stopCinema();state=fresh;selected=0;paused=false;speed=1;closeModal();toast('正常小店已暂存，看看题目再开门。');}break;}
 case'challenge-exit':{const career=E.resumeCareer(state);if(!career){toast('原存档暂未恢复，当前进度已保留，请勿重开。');break;}state=career;selected=0;paused=state.phase==='service';closeModal();toast('回到自己的小店啦，经营进度原样保留。');break;}
 case'challenge-poster':shareCard(state.challenge.name,state.challenge.code+' · '+(state.stats.goal?'挑战成功':'我的新尝试'),[state.challenge.desc,'用时 '+Math.ceil(state.elapsed)+' 秒，拼桌 '+state.stats.shared+' 次。',...state.stats.records.map(r=>r.guest+'：'+r.broths.map(b=>E.B[b].name).join('/')+'；'+r.rounds.map(r=>r.map(id=>E.F[id].short).join('+')).join(' → ')+'。¥'+r.price+'，'+r.score+' 分'+(r.wishes.photo?'，油碟合影完成':''))],'挑战小票');break;
 case'save-poster':savePoster();break;case'cinema':cinemaModal();break;case'cinema-play':{const v=$('#opera-video');if(v){if(v.error)v.load();v.currentTime=0;v.play().catch(()=>toast('请点播放器的播放按钮。'));}break;}
 case'cinema-mute':{const v=$('#opera-video');if(v){v.muted=!v.muted;$('[data-action="cinema-mute"]').textContent=v.muted?'开启舞台声音':'舞台静音';}break;}
 default:return false;
 }save();render();return true;}

function dispatch(action,id,target){if(neighborhoodAction(action,id))return;if(action==='reset-confirm'&&state.challenge){modal('重新挑战这道题？','正常小店仍会完整保留',`<p class="modal-intro">重置本次挑战的库存和客人，可以换一种安排再试。</p>`,'challenge-reset',`<div class="modal-footer"><button data-action="modal-close">继续这一局</button><button class="primary" data-action="challenge-retry">重新挑战</button></div>`);return;}if(action==='next'&&state.challenge){neighborhoodAction('challenge-exit');return;}switch(action){case'owner':ownerModal();break;case'owner-talk':ownerAct('hello');chime();break;case'owner-tea':{const msg=E.hostTea(state);if(msg)toast(msg);else{closeModal();ownerAct('tea','来，嬢嬢请一壶茶！忙归忙，先润润嗓子。');chime('dish');save();render();}break;}case'plan-choice':{const t=state.tables[planTable];draft=id==='custom'?{...E.defaultPlan(state,t.guest),rounds:[[],[],[]],choice:'custom',discreet:false}:E.clone(E.planChoices(state,t).find(c=>c.id===id).plan);planStep=0;renderPlan();break;}case'rechoose':delete draft.choice;renderPlan();break;case'cat-auto':state.cats[Number(id)].auto=!state.cats[Number(id)].auto;catsModal();save();break;case'seats':seatModal();break;case'move-seat':{const msg=E.moveTable(state,selected,Number(id));if(msg)toast(msg);else{selected=Number(id);closeModal();render();save();}break;}case'show-type':state.showPlan.type=id;showModal();save();break;case'show-schedule':{const val=$('#show-time').value;E.scheduleShow(state,state.showPlan.type,val==='manual'?null:Number(val));save();toast('场次安排好啦');showModal();break;}case'opera-normal':if(E.show(state,0)){chime('opera-start');cinemaModal();save();render();}break;case'opera-rhythm':rhythmModal();break;case'help':helpModal();break;case'more':moreModal();break;case'plan-step':planStep=Number(id);renderPlan();$('#modal').scrollTop=0;break;case'plan-next':planStep=Math.min(2,planStep+1);renderPlan();$('#modal').scrollTop=0;break;case'plan-back':planStep=Math.max(0,planStep-1);renderPlan();$('#modal').scrollTop=0;break;case'modal-close':closeModal();break;case'mode':state.mode=id;render();save();break;case'open':E.open(state);selected=0;paused=false;$('#owner-quote').textContent='老罗来啦，给他留一半清汤嘛。';render();save();chime('open');break;case'pause':if(state.phase==='service'){paused=!paused;render();}else toast('开门后可以随时暂停。');break;case'speed':speed=speed===1?2:speed===2?3:1;render();toast('营业速度 '+speed+'×');break;case'sound':soundModal();break;case'audio-mute':sound.set('muted',!sound.settings.muted);state.muted=sound.settings.muted;save();break;case'audio-retry':sound.retry();break;case'audio-preview':if(sound.settings.muted){toast('先点「开启声音」，再试听。');break;}sound.unlock().then(()=>chime(id));break;case'select':selected=Number(id);render();if(innerWidth<=600){const main=$('.main-layout'),desk=$('[data-table="'+selected+'"]');if(desk)main.scrollTo({top:Math.max(0,main.scrollTop+desk.getBoundingClientRect().top-main.getBoundingClientRect().top-(main.clientHeight-$('.notebook').offsetHeight)/2),behavior:'smooth'});}if(state.tables[selected]?.status==='dirty')toast('点右侧「亲自收台」，或等员工自动收拾。');break;case'plan':openPlan(Number(id));break;case'pot':draft.pot=id;draft.broths=Array.from({length:E.P[id].n},(_,i)=>draft.broths[i]||(i%2?'clear':'red'));renderPlan();break;case'round':activeRound=Number(id);renderPlan();break;case'food':draft.rounds[activeRound] ||= [];if(draft.rounds[activeRound].length>=2){toast('这一轮两盘够啦，换到下一轮。');break;}draft.rounds[activeRound].push(id);renderPlan();chime();break;case'remove-food':{let [i,j]=id.split(',').map(Number);draft.rounds[i].splice(j,1);renderPlan();break;}case'recommend':draft={...E.defaultPlan(state,state.tables[planTable].guest),choice:'custom'};renderPlan();break;case'clear-plan':draft.rounds=[[],[],[]];renderPlan();break;case'serve':{let r=E.serve(state,planTable,draft);if(r.errors.length){toast(r.errors.join('，'));break;}closeModal();pop(planTable,'开锅啦！');ownerAct('serve','这一锅安排妥当，开涮！');chime('serve');save();break;}case'save-recipe':{let name=$('#recipe-name').value.trim()||'梅嬢嬢的招牌锅';if(!draft.rounds.flat().length)return toast('先放几道菜，再存招牌。');if(state.recipes.length>=6)return toast('招牌本放满啦，先在菜单里移掉一份。');state.recipes.push({name,plan:E.clone(draft)});save();toast('「'+name+'」已存进招牌菜单');break;}case'delete-recipe':state.recipes.splice(Number(id),1);save();recipeModal();break;case'pet':selected=Number(id);catsModal();break;case'cat-assign':{let cat=Number(id),tid=Number($('#cat-table-'+id).value),t=state.tables[tid];if(!t)return; let msg=E.pet(state,tid,cat);if(msg)toast(msg);else{pop(tid,'♡ 猫来啦');chime('cat');toast(state.cats[cat].name+'陪客人玩起来啦');}save();render();catsModal();break;}case'clean':{let t=state.tables[Number(id)];if(t?.status==='dirty'){t.status='empty';ownerAct('clean','桌子擦亮，下一桌街坊有地方坐！');pop(id,'收拾妥当！');chime('clean');render();save();}break;}case'add':{let msg=E.addDish(state,Number(id));if(msg)toast(msg);else{chime('dish');pop(id,'再来一盘！');render();save();}break;}case'stock':stockModal();break;case'buy':if(E.buy(state,id)){chime('buy');stockModal();render();save();}else toast('钱不够或食材还未解锁。');break;case'restock':{let ids=['mushroom','beef','tofu','greens'];if(state.cash<108)return toast('常用四样补货需要 ¥108。');ids.forEach(id=>E.buy(state,id));chime('buy');stockModal();render();save();toast('四样常用食材各补好了 4 份。');break;}case'upgrade':upgradesModal();break;case'upgrade-buy':if(E.upgrade(state,id)){chime('fanfare');toast(E.UP[id].name+'，安排好了！');upgradesModal();render();save();}break;case'cats':catsModal();break;case'regulars':regularsModal();break;case'events':case'event-detail':eventsModal();break;case'recipes':recipeModal();break;case'ledger':ledgerModal();break;case'settlement':settlementModal();break;case'next':E.next(state);paused=false;selected=0;closeModal();render();save();toast(state.day<=7?'第 '+state.day+' 天，新故事来了。':'老街日常继续，熟客和招牌都还在。');break;case'receipt':receiptModal(Number(id));break;case'download-receipt':{let r=state.stats.records[Number(id)],txt=`一锅江湖 · 本桌小票\n第 ${state.day} 天\n${r.guest}\n${E.P[r.pot].name}\n${r.rounds.map((r,i)=>'第 '+(i+1)+' 轮：'+r.map(id=>E.F[id].name).join('、')).join('\n')}\n餐费 ${r.price} / 小费 ${r.tips}\n评价 ${r.score}\n「${r.quote}」\n${r.reasons.join('\n')}`;let a=document.createElement('a'),url=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='一锅江湖-第'+state.day+'天小票.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('本桌小票已准备下载');break;}case'show':showModal();break;case'opera-start':startOpera();break;case'opera-hit':operaHit();break;case'close':if(state.phase!=='service'||state.closing)return;modal('提前挂上打烊牌？','把现在的客人照顾完',`<p class="modal-intro">停止接待后面的预约，当前桌仍会继续用餐。尚未到店的 ${Math.max(0,state.schedule.length-state.nextGuest)} 桌不会再来；可能影响今日事件目标。</p>`,'close-confirm',`<div class="modal-footer"><button data-action="modal-close">继续迎客</button><button class="primary" data-action="close-confirm">不再接新客，照顾完这几桌</button></div>`);break;case'close-confirm':state.closing=true;state.schedule=state.schedule.slice(0,state.nextGuest);closeModal();if(state.tables.every(t=>t.status==='empty')){E.closeDay(state);render();settlementModal();}save();break;case'reset-confirm':modal('另起一锅江湖？','这一操作会清空当前浏览器里的游戏进度',`<p class="modal-intro">现金、熟客、猫咪亲近度和招牌菜单会重置。从第一天四张桌重新开始。</p>`,'reset',`<div class="modal-footer"><button data-action="modal-close">留着这间店</button><button class="primary" data-action="reset">确认重新开店</button></div>`);break;case'reset':state=E.fresh();paused=false;selected=0;closeModal();render();save();toast('新店开张，锅还是热的。');break;}}
document.addEventListener('pointerdown',()=>sound.unlock(),{passive:true});
document.addEventListener('click',e=>{sound.unlock();let b=e.target.closest('[data-action]');if(!b||b.disabled)return;if(b.tagName==='A')e.preventDefault();dispatch(b.dataset.action,b.dataset.id,b);});
document.addEventListener('input',e=>{if(e.target.matches('[data-volume]')){const k=e.target.dataset.volume,v=Number(e.target.value);sound.set(k,v/100);$('#volume-'+k).textContent=v+'%';}});
document.addEventListener('change',e=>{if(e.target.id==='pair-source'){pairSource=e.target.value;pairModal();}if(e.target.id==='pair-target'){pairTarget=Number(e.target.value);pairModal();}if(e.target.id==='plan-signature'){draft.signature=e.target.value||null;renderPlan();}if(e.target.matches('[data-broth]')){draft.broths[Number(e.target.dataset.broth)]=e.target.value;renderPlan();}if(e.target.matches('[data-plan-toggle]')){let k=e.target.dataset.planToggle;draft[k]=k==='sauce'?(e.target.checked?'luo':null):e.target.checked;renderPlan();}if(e.target.id==='small-portion'){draft.small=e.target.checked;renderPlan();}});
document.addEventListener('keydown',e=>{sound.unlock();if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.code==='Space'){if(opera?.running){e.preventDefault();operaHit();}else if(!$('#modal').open){e.preventDefault();dispatch('pause');}}if(!$('#modal').open&&/^[1-6]$/.test(e.key)){let i=Number(e.key)-1;if(state.tables[i]){selected=i;render();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)$('#opera-video')?.pause();if(opera?.running){if(document.hidden)opera.hiddenAt=performance.now();else if(opera.hiddenAt){opera.start+=performance.now()-opera.hiddenAt;opera.hiddenAt=0;}}syncSound();if(document.hidden&&state.phase==='service'){paused=true;save();render();}});window.addEventListener('pagehide',()=>{$('#opera-video')?.pause();save();sound.update({hidden:true});});window.addEventListener('pageshow',syncSound);
let renderAccum=0;function loop(now){let dt=Math.min(.2,(now-last)/1000);last=now;if(opera?.running&&!document.hidden){let cycle=Math.floor((now-opera.start)/2200);if(opera.lastCycle!==cycle){opera.lastCycle=cycle;chime('drum');}let p=((now-opera.start)%2200)/2200;let pin=$('#rhythm-pin');if(pin)pin.style.left=(p*100)+'%';}if(!paused&&!$('#modal').open&&!document.hidden&&state.phase==='service'){let phase=state.phase;let prevServed=state.stats.served;let before=state.tables.map(t=>({status:t.status,round:t.round}));E.tick(state,dt*speed);if(state.tables.some((t,i)=>t.status==='eating'&&before[i]?.status==='waiting'))chime('serve');else if(state.tables.some((t,i)=>t.status==='eating'&&t.round!==before[i]?.round))chime('dish');renderAccum+=dt;if(state.stats.served>prevServed){ownerAct('cheer','吃得巴适就常来，嬢嬢给你留位置！');chime('coin');toast('客人结账啦！'+state.logs[0]);}if(phase!==state.phase){chime(state.stats.goal?'fanfare':'close');save();render();settlementModal();}else if(renderAccum>.6){renderAccum=0;render();}saveTimer+=dt;if(saveTimer>=3){saveTimer=0;save();}}requestAnimationFrame(loop);}render();requestAnimationFrame(loop);
if(state.phase==='settlement')setTimeout(settlementModal,150);
